import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.Bb5YUzRP.js";import{Ct as i,wt as a}from"./chunks/assets.8isJ-IUK.js";var o=JSON.parse(`{"title":"Grids","description":"","frontmatter":{},"headers":[],"relativePath":"grids.md","filePath":"grids.md"}`),s={name:`grids.md`},c=a+` 1x, `+i+` 2x`;function l(e,i,a,o,s,l){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="grids" tabindex="-1">Grids <a class="header-anchor" href="#grids" aria-label="Permalink to “Grids”">​</a></h1><p>You can use grids to vary the value of a field based on two other fields.</p><p><img src="/webp/grid.png-90-1788222277556.webp" srcset="`+c+`" alt="Grids" title="" width="1272" height="828" loading="lazy" style="width:636px;"></p><p>In this case, the <code>price_m2</code> field is being varied based on the <code>width</code> and <code>height</code> fields.</p><p>A column is picked when the column field is equal or greater than the column value.</p><p>The same logic applies to the row field.</p><p>Here are some examples to clarify this:</p><ul><li><code>width</code> equals 10: The first column is picked because <code>0 &lt;= 10 &lt; 100</code></li><li><code>width</code> equals 100: The second column is picked because <code>100 &lt;= 100 &lt; 200</code></li></ul><p>If the column field is greater than the last column value, the last column is picked.</p><ul><li><code>width</code> equals 250: The third column is picked because <code>200 &lt;= 250</code></li></ul><p>So following this logic, if the <code>width</code> is 75 and the <code>height</code> is 150, the <code>price_m2</code> will be 6.</p><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>It is recommended to use the <a href="/formula-functions.html#the-grid-function"><code>Grid</code> formula</a> function instead of the <code>Grids</code> feature because it&#39;s more efficient and more flexible.</p></div>`,12)]])}var u=e(s,[[`render`,l]]);export{o as __pageData,u as default};